"""Generate the Part S result documents from results.json and the tables of `sh_s2` to `sh_s5` (SIMULATED_HW_FORMAT):

    docs/03_results/SIMHW_RESULTS.md       summary, S2 failure map and tables, S3 policy table and latency decomposition, S5 table
    docs/03_results/SIMHW_S4_CASES.md      the one list of security cases (58 repository cases and the S01 to S09 scenarios)

    python -m crashguard.sh_docs
"""
from __future__ import annotations

import json
from pathlib import Path

import pandas as pd

R = {e["name"]: e["value"] for e in json.loads(Path("results/results.json").read_text(encoding="utf-8")) if e["name"].startswith(("sh.", "ar.r4"))}
T = Path("results/tables")
HDR = ["<!-- header:start -->", "<!-- header:end -->", ""]
WORDING = ("Evaluated on simulated hardware-format logs generated from stated sensor and link models; no real hardware measurements are reported.")


def f(x, nd=3):
    return "NOT_RUN" if x is None or (isinstance(x, float) and x != x) else (f"{x:.{nd}f}" if isinstance(x, float) else str(x))


def md_table(df: pd.DataFrame, cols: list[str], heads: list[str], nd=3) -> list[str]:
    out = ["| " + " | ".join(heads) + " |", "|" + "---|" * len(heads)]
    for _i, r in df.iterrows():
        out.append("| " + " | ".join(f(r[c], nd) for c in cols) + " |")
    return out


def results_doc() -> str:
    s2 = pd.read_csv(T / "sh_s2_variants.csv")
    s3 = pd.read_csv(T / "sh_s3_policies.csv")
    conf = json.loads((T / "sh_s2_confusion.json").read_text(encoding="utf-8"))
    L = ["# Simulated hardware-format validation: results (Part S)", ""] + HDR
    L += [f"**Wording for the abstract, methods and table captions.** {WORDING} H5 edge timing stays NOT_RUN: the simulated timings are placeholders. N2, N5, N6 and N7 stay NOT_YET for hardware.", "",
          "Generated by `python -m crashguard.sh_docs` from `results/results.json` (keys `sh.*`). Design, thresholds and kill rules: `docs/02_preregistration/PREREGISTRATION_V11.md`. "
          "The files are simulated by `hwsim.py` and `hwsim_v2.py`; the base variant is correct by construction, so the result that matters is where the pipeline breaks. Nothing here is hardware evidence.", ""]
    L += ["## Verdicts of family S (Holm is applied in `docs/03_results/COMBINED_VERDICTS.md`)", "",
          "| Hypothesis | Statement (short) | Criterion met | Raw p |", "|---|---|---|---|",
          f"| H-S1 | side accuracy >= 0.90 in every sensor variant and the supplied set | {'yes' if R['sh.s2.hS1.criterion_met'] else 'no'} ({R['sh.s2.hS1.n_variants_below_0.90']} of 16 below 0.90) | {R['sh.s2.hS1.p_raw']} |",
          f"| H-S2 | recall >= 0.90 and false-alarm rate <= 0.10 at the 2 g trigger in every sensor variant | {'yes' if R['sh.s2.hS2.criterion_met'] else 'no'} (recall ok in {R['sh.s2.hS2.n_variants_recall_ok']} of 16, false-alarm rate ok in {R['sh.s2.hS2.n_variants_far_ok']} of 16) | {R['sh.s2.hS2.p_raw']} |",
          f"| H-S3 | UA-SCT at least fixed-3 minus 0.02 on the four edge runs, no airtime above the allowance | {'yes' if R['sh.s3.hS3.criterion_met'] else 'no'} (the point differences pass; the interval at 34 dB is wide) | {R['sh.s3.hS3.p_raw']} |",
          f"| H-S4 | median trigger-to-ACK of first-try deliveries >= 500 ms | {'yes' if R['sh.s3.hS4.criterion_met'] else 'no'} (median {f(R['sh.s3.h7.supplied.median_first_try_ms'], 0)} ms) | {R['sh.s3.hS4.p_raw']} |",
          f"| H-S5 | no accepted attack on the real suite and scenarios; persisted counter | {'yes' if R['sh.s4.hS5.criterion_met'] else 'no'} (0 of {R['sh.s4.scenarios.attack_attempts_counted']} attack attempts accepted) | {R['sh.s4.hS5.p_raw']} |",
          f"| H-S6 | SW-420 confirmation: false-alarm reduction >= 0.02, recall loss <= 0.02 | {'yes' if R['sh.s5.hS6.criterion_met'] else 'no'} (reduction {f(R['sh.s5.base_range_1.5_4.0.pooled.far_reduction'])}, recall loss {f(R['sh.s5.base_range_1.5_4.0.pooled.recall_loss'])}) | {R['sh.s5.hS6.p_raw']} |", ""]
    # S2
    L += ["## S2: trigger and impact-side rules on the variants (H-S1, H-S2)", "",
          "Rule: trigger at 2.0 g on the magnitude (gravity included), impact side from the horizontal impulse over the initial 60 ms with the stored calibration signs (x +1, y -1). "
          "Side accuracy counts the 80 horizontal crash events per variant (40 in the supplied set); an event with no trigger counts as wrong. Intervals: bootstrap of events, 2,000 resamples.", "",
          *md_table(s2, ["variant", "side_acc", "side_acc_lo", "side_acc_hi", "recall", "recall_lo", "recall_hi", "far", "far_lo", "far_hi", "transfer_recall", "transfer_far"],
                    ["Variant", "Side accuracy", "lo", "hi", "Crash recall", "lo", "hi", "Non-crash false-alarm rate", "lo", "hi", "Forest recall (transfer)", "Forest false-alarm rate (transfer)"]), "",
          "### Failure map (smallest fault, in the preregistered order, at which a criterion fails)", "", "| Fault family | Side accuracy below 0.90 | Crash recall below 0.90 | False-alarm rate above 0.10 |", "|---|---|---|---|"]
    fam = ["tilt about x", "tilt about y", "axis sign flip x", "axis sign flip y", "sampling rate", "timestamp jitter", "dropped samples", "noise", "bias", "crash peak (decreasing)"]
    for a in fam:
        k = a.replace(" ", "_")
        L.append(f"| {a} | {R[f'sh.s2.failure_map.{k}.side_accuracy_below_0.90']} | {R[f'sh.s2.failure_map.{k}.crash_recall_below_0.90']} | {R[f'sh.s2.failure_map.{k}.non-crash_false-alarm_rate_above_0.10']} |")
    L += ["", "Reading. The side rule keeps 0.90 or more under every tilt up to 30 degrees, under noise x4, bias sd 0.08 g, jitter, dropped samples and crash peaks down to a 3 g median (exactly 0.900 at 3 g). "
          "It fails under the two axis-sign flips (front and rear swap under an x flip, left and right under a y flip: accuracy near 0.5) and at 10 Hz sampling (accuracy 0.26: a 12 to 45 ms pulse is mostly missed). "
          "The trigger alone has a false-alarm rate of 0.6 to 0.7 on these bench non-crash events (ramp bumps, rough driving and some hand taps exceed 2 g), so the trigger cannot separate crash from non-crash here; "
          "the forest of the transfer test rejects most bench pulses (recall 0.07 to 0.5): bench pulses are 12 to 45 ms against 80 to 150 ms for vehicle crashes, so that test checks plumbing and scale handling, not real transfer.", "",
          "### Confusion of the impact-side rule (base variant and the failing variants; rows are the true side)", ""]
    for v in ("V00_base", "F_x", "F_y", "S_10Hz"):
        L += [f"**{v}**", "", "| True side | front | rear | left | right | no trigger |", "|---|---|---|---|---|---|"]
        for side, row in conf[v].items():
            L.append(f"| {side} | {row['front']} | {row['rear']} | {row['left']} | {row['right']} | {row['no_trigger']} |")
        L.append("")
    L += ["The vertical crash events (20 per variant) have no class in the rule; they trigger in all variants except 10 Hz, where 40% trigger.", ""]
    # S3
    sup = s3[(s3.set == "supplied") & (s3.duty == 0.10)]
    L += ["## S3: link logs and policies (H-S3), duty 10%", "",
          "The loss in each direction is calibrated from the log of each edge run: q = deliveries / attempts, p = 1 - sqrt(q). One car, SF7, 40 paired seeds, critical class. P0 fixed 3 retries, P1 severity table, P4 UA-SCT with the fast-path cap; "
          "khan and tamang are minimal re-implementations that send at once with no driver-cancel window (ASSUMPTIONS in `sh_s3.mini_baselines`), so their latency is not comparable with the 5 to 10 s hold of P0 and P1. "
          "Latencies are ACK-confirmed, in seconds, over delivered events; Tamang-style has no ACK, so its latency is base receipt. 'Airtime share' is the node airtime over the duty allowance (1 = the whole 10% allowance).", "",
          *md_table(sup, ["run", "policy", "p_dir", "log_final", "log_first_try", "reach10_critical", "reach30_critical", "delivered_critical", "median_lat_s", "p95_lat_s", "node_air_share", "node_air_share_max"],
                    ["Run", "Policy", "p per direction", "Log: final delivery", "Log: first-try delivery", "Reach within 10 s", "Reach within 30 s", "Delivered (any time)", "Median latency (s)", "p95 latency (s)", "Airtime share (mean)", "Airtime share (max)"]), "",
          f"Largest airtime share of any policy on the supplied edge runs: {f(R['sh.s3.hS3.max_node_air_share'], 4)} of the 10% allowance (the allowance is never exceeded). "
          "Paired difference UA-SCT minus fixed-3, critical reach within 10 s: " + "; ".join(f"{k} {f(R[f'sh.s3.hS3.{k}.diff_P4_minus_P0'], 4)} [{f(R[f'sh.s3.hS3.{k}.diff_lo'], 4)}, {f(R[f'sh.s3.hS3.{k}.diff_hi'], 4)}], p {R[f'sh.s3.hS3.{k}.p_raw']}" for k in ("H3-edge-30db", "H3-edge-34db", "H3-edge-38db", "H3-edge-42db")) + ".", "",
          "Reading. At 30 dB all policies reach the base (final delivery 1.0; first-try 0.74). At 34 dB the severity table (P1) reaches 0.956 within 10 s against 0.746 for fixed-3 and 0.735 for UA-SCT, which reaches 0.992 within 30 s: "
          "UA-SCT spaces its rounds and is slower here. At 38 dB and 42 dB the log has almost no delivery; the gains of UA-SCT (0.89 and 0.70 delivered any time) come from the simulator's assumption that each spreading-factor step lowers the loss "
          "by a factor 0.7 (`sct_sim`), so they are a property of that assumption, not of the logs. The non-inferiority test at 34 dB cannot show a difference smaller than 0.02 (interval about -0.07 to +0.05).", ""]
    h = {k.replace("sh.s3.h7.supplied.", ""): v for k, v in R.items() if k.startswith("sh.s3.h7.supplied.")}
    L += ["## S3: end-to-end latency (H-S4), supplied H7 file", "",
          f"Median trigger-to-ACK of {h['n_first_try']} first-try deliveries: {f(h['median_first_try_ms'], 0)} ms (p95 {f(h['p95_first_try_ms'], 0)} ms); all ACKed events: median {f(h['median_all_acked_ms'], 0)} ms. "
          f"Decomposition of the median first-try event: post-trigger window {f(h['window_ms'], 0)} ms + compute {f(h['compute_ms'], 0)} ms + wait before transmit {f(h['wait_tx_ms'], 0)} ms + alert airtime {f(h['alert_air_ms'], 0)} ms + base turnaround {f(h['base_turn_ms'], 0)} ms + ACK airtime {f(h['ack_air_ms'], 0)} ms. "
          f"ANALYTICAL lower bound before compute and waiting: 250 + 169.2 + 61.7 = {f(R['sh.s3.h7.analytic.lower_bound_ms'], 1)} ms. Each retry adds about 600 ms. "
          "A \"sub-500 ms\" statement therefore fails for this window, alert and ACK at SF7 unless the post-trigger window is shortened or the ACK is not waited for; this is a statement about the model, not the radio.", ""]
    # S5
    pool = {a: {k.split(".pooled.")[1]: v for k, v in R.items() if k.startswith(f"sh.s5.{a}.pooled.")} for a in ("base_range_1.5_4.0", "range_0.8_2", "range_3_6")}
    L += ["## S5: IMU only against IMU plus SW-420 confirmation (H-S6)", "",
          "Rule: at least 2 of 6 switches within -100 to +300 ms of the trigger. Pooled over the 15 sensor variants (1,500 crash and 1,500 non-crash events). Exact McNemar test on the non-crash events (the discordant pairs all go one way).", "",
          "| Switch threshold range | False-alarm rate, IMU only | IMU + SW-420 | Reduction [95% interval] | Crash recall, IMU only | IMU + SW-420 | Loss [95% interval] | McNemar b | Criterion met |", "|---|---|---|---|---|---|---|---|---|"]
    for a, nm in (("base_range_1.5_4.0", "1.5 to 4.0 g (base)"), ("range_0.8_2", "0.8 to 2.0 g"), ("range_3_6", "3.0 to 6.0 g")):
        p = pool[a]
        L.append(f"| {nm} | {f(p['far_imu'])} | {f(p['far_imu_sw'])} | {f(p['far_reduction'])} [{f(p['far_reduction_lo'])}, {f(p['far_reduction_hi'])}] | {f(p['recall_imu'])} | {f(p['recall_imu_sw'])} | {f(p['recall_loss'])} [{f(p['recall_loss_lo'])}, {f(p['recall_loss_hi'])}] | {p['mcnemar_b']} | {'yes' if (p['far_reduction'] >= 0.02 and p['recall_loss'] <= 0.02) else 'no'} |")
    L += ["", "Reading. With the base switch model the confirmation removes 0.29 of the false alarms but costs 0.043 of the crash recall (weak crashes do not shake enough switches), so the preregistered criterion fails on the recall loss. "
          "With low switch thresholds (0.8 to 2.0 g) it costs no recall but removes only 0.032; with high thresholds (3.0 to 6.0 g) it removes 0.57 and costs 0.27 of the recall. "
          "Any gain therefore depends on the simulator's assumption about switch sensitivity; a real SW-420 result needs the author's logs.", "",
          "Per-variant values are in `results/tables/sh_s5_variants.csv`.", ""]
    L += ["## S4: security (H-S5)", "",
          f"One number: the repository's suite has {R['sh.s4.suite.total']} cases ({R['sh.s4.suite.base']} base, {R['sh.s4.suite.extension']} extension), all {R['sh.s4.suite.matching_expected']} behave as expected; "
          f"the cases are listed once in `docs/03_results/SIMHW_S4_CASES.md`. {R['sh.s4.suite.note_30_and_38']}. "
          f"Counter behaviour: the reference verifier persists its counter ({'yes' if R['sh.s4.counter.reference_verifier_persists'] else 'no'}: an older alert after a base reboot is not accepted); a RAM-only verifier accepts it ({'yes' if R['sh.s4.counter.ram_only_accepts_old_alert'] else 'no'}), which is the S06 finding of the simulated model; "
          f"a car whose counter restarts is rejected ({'yes' if R['sh.s4.counter.car_restart_rejected'] else 'no'}), the S08 availability cost. The ESP32 firmware is not in this repository, so what it implements is {R['sh.s4.counter.firmware']}. "
          "The documented gaps stay: a base that loses its counter accepts a recorded alert again, and an alert for another node id signed with the shared key is accepted; R1 and R4 address them.", ""]
    return "\n".join(L)


def cases_doc() -> str:
    suite = pd.read_csv(T / "sh_s4_suite.csv")
    sc = pd.read_csv(T / "sh_s4_scenarios.csv")
    h4 = pd.read_csv(T / "sh_s4_h4_file.csv")
    L = ["# Security cases (S4): one list", ""] + HDR
    L += [f"The repository's suite has {len(suite)} cases: {int((suite.suite == 'base').sum())} in `attacks.run_cases` (`attacks.cases_total`) and {int((suite.suite == 'extension').sum())} in `attacks_extra.run_cases`. "
          f"{int(suite.match.sum())} behave as expected. Categories: " + ", ".join(f"{k} {v}" for k, v in suite.category.value_counts().items()) + ". "
          "The figures 30 and 38 from earlier notes are not found in any current file or key. Origin of every row: SIMULATED_HW_FORMAT (the real code run in software; no radio).", "",
          "| Suite | # | Case | Expected | Observed | Match | Category |", "|---|---|---|---|---|---|---|"]
    for _i, r in suite.iterrows():
        L.append(f"| {r.suite} | {r.idx} | {str(r.case).replace('first', 'initial')} | {r.expected} | {r.observed} | {'yes' if r.match else 'NO'} | {r.category} |")
    L += ["", "## Scenarios S01 to S09 of the simulated H4 file, re-run on the real verifier (10 attempts each)", "", "| Scenario | Attempts | Attacks accepted | Decisions |", "|---|---|---|---|"]
    for name, g in sc.groupby("scenario", sort=True):
        L.append(f"| {name} | {len(g)} | {int(g.attack_succeeded.sum())} | {'; '.join(f'{k} x{v}' for k, v in g.decision.value_counts().items())} |")
    L += ["", "S06m is the model of a base that does not persist its counter: it accepts the old alert, as the simulated model said. It is not counted as an attack on the repository's verifier.", "",
          "## Outcomes recorded in the supplied `security_H4.json` (the simulated model, 10 attempts per scenario)", "", "| Case | Scenario | Base result |", "|---|---|---|"]
    for _i, r in h4.iterrows():
        L.append(f"| {r.case_id} | {r.scenario} | {r.base_result} |")
    L.append("")
    return "\n".join(L)


def main() -> None:
    Path("docs/03_results/SIMHW_RESULTS.md").write_text(results_doc(), encoding="utf-8")
    Path("docs/03_results/SIMHW_S4_CASES.md").write_text(cases_doc(), encoding="utf-8")
    print("written")


if __name__ == "__main__":
    main()
